SELECT (SELECT count(*) FROM "User") AS users, (SELECT count(*) FROM "Employee") AS employees, (SELECT count(*) FROM "AssemblyTeamMember") AS assembly_team_members, (SELECT count(*) FROM "AssemblyPartner") AS assembly_partners, (SELECT count(*) FROM "StockPartner") AS stock_partners, (SELECT count(*) FROM "FactoryWorker") AS factory_workers, (SELECT count(*) FROM "SalesRepIdentity") AS sales_rep_identities, (SELECT count(DISTINCT "salesRep") FROM "Deal") AS distinct_deal_sales_reps
